<script setup lang="ts">
import { computed } from 'vue'
import { useExperimentStore, usePredictionStore, useSystemStore, useKronosStore, useTradeStore, useInterfaceStore } from '../../stores'
import { useInstrument } from '../../composables/useInstrument'
import { money, percent } from '../../format'
import StatusBadge from '../../components/StatusBadge.vue'
const system=useSystemStore();const prediction=usePredictionStore();const kronos=useKronosStore();const trades=useTradeStore();const ui=useInterfaceStore();const experiments=useExperimentStore();const {symbol,timeframe}=useInstrument()
const decision=computed(()=>prediction.current?.decisions[ui.profile]);const details=computed(()=>decision.value&&typeof decision.value==='object'&&!Array.isArray(decision.value)?decision.value:{})
const version=computed(()=>{const v=prediction.current?.features.strategy_version ?? prediction.current?.features.strategyVersion;return typeof v==='string'?v:trades.open.find(t=>t.profile===ui.profile&&t.classification==='SIMULATED_SHADOW')?.strategyVersion ?? 'UNKNOWN'})
const ev=computed(()=>{const value=details.value.expected_value ?? prediction.current?.expected_value;return value==null?null:Number.isFinite(Number(value))?Number(value):null})
const active=computed(()=>experiments.experiments.find(e=>e.id===ui.profile))
</script>
<template><section class="card agent-card" data-testid="agent-card"><div class="panel-heading"><div><span class="eyebrow">TRADE AI</span><h2>Autotrading</h2></div><StatusBadge :value="system.status?.paperAuto ?? 'UNKNOWN'" /></div><div class="agent-market"><span>{{ symbol }}</span><span class="pill">{{ timeframe }}</span></div><dl class="agent-parameters"><div><dt>Estrategia Shadow · versión</dt><dd>{{ version }}</dd></div><div><dt>Perfil Shadow observado</dt><dd>{{ ui.profile }} · {{ active?.status ?? 'DATA_UNAVAILABLE' }}</dd></div><div><dt>Estrategia Paper · versión</dt><dd>{{ system.rotation?.strategyVersion ?? 'UNKNOWN' }}</dd></div><div><dt>Modo de ejecución</dt><dd>SHADOW · Paper {{ system.rotation?.operationalState ?? "UNKNOWN" }}</dd></div><div><dt>Kronos / calibración</dt><dd>{{ kronos.view?.operationalHealth ?? 'UNKNOWN' }} · {{ kronos.view?.calibrationState ?? 'UNKNOWN' }}</dd></div><div><dt>Probabilidad empírica</dt><dd>{{ system.connection==='CONNECTED'?percent(prediction.current?.probability):'STALE' }}</dd></div><div><dt>Régimen de mercado</dt><dd>{{ prediction.current?.regime ?? 'UNKNOWN' }}</dd></div><div><dt>EV neta · USD</dt><dd>{{ money(ev) }}</dd></div></dl><div class="decision-box"><StatusBadge :value="String(details.decision ?? prediction.current?.decision ?? 'INSUFFICIENT_EVIDENCE')" /><p>{{ details.reason ?? prediction.current?.status ?? 'DATA_UNAVAILABLE' }}</p></div><div class="agent-actions"><RouterLink class="primary-button" :to="trades.open.length?'/trading':'/research'">{{ trades.open.length?'Ver operación':system.studyStatus==='SHADOW_RESEARCH_RUNNING'&&system.connection==='CONNECTED'&&!system.error?'Observando · ver research':'Ver investigación' }}</RouterLink><button class="secondary-button" @click="ui.openSol">¿Por qué no entramos?</button></div><small>La interfaz observa. El runner se controla mediante sus comandos protegidos.</small></section></template>
